mapper.select:
SELECT type_id AS typeId,
       target_category AS targetCategory,
       target_id AS targetId,
       extend::text AS extendJson
FROM public.type_relations tr
WHERE game_id = #{gameId}
  AND target_category = #{targetCategory}
  AND target_id = #{targetId}
  AND COALESCE((to_jsonb(tr) ->> 'deleted')::boolean, FALSE) = FALSE
ORDER BY type_id

SELECT type_id AS typeId,
       target_category AS targetCategory,
       target_id AS targetId,
       extend::text AS extendJson
FROM public.type_relations tr
WHERE game_id = #{gameId}
  AND type_id = #{typeId}
  AND target_category = #{targetCategory}
  AND target_id = #{targetId}
  AND COALESCE((to_jsonb(tr) ->> 'deleted')::boolean, FALSE) = FALSE

choose.when:
UPDATE public.type_relations
SET start_version_id = #{versionId},
    end_version_id = #{versionId},
    deleted = TRUE,
    updated_at = NOW()
WHERE game_id = #{gameId}
  AND type_id = #{typeId}
  AND target_category = #{targetCategory}
  AND target_id = #{targetId}

choose.otherwise:
DELETE FROM public.type_relations
WHERE game_id = #{gameId}
  AND type_id = #{typeId}
  AND target_category = #{targetCategory}
  AND target_id = #{targetId}

mapper.update:
